/**
 * hypothesis.ts — Manual six-world scratchpad builder.
 *
 * This module is Kiro work (2026-10-31). It has no dependency on DOM, React,
 * Next.js, AI, storage, solver, or private answer data.
 *
 * The inherited application (engine, renderer, generator, components) is Codex work.
 */

import type { Locale, Suspect, SuspectId } from "./types";

/** A stable identifier encoding culpritId and fact. Six legal values exist. */
export type HypothesisId = `${SuspectId}-false` | `${SuspectId}-true`;

/** One entry in the six-world Cartesian product used as a player scratchpad. */
export type Hypothesis = {
  /** Stable ID derived from culpritId and fact; suitable as a React key and data-testid suffix. */
  readonly id: HypothesisId;
  readonly culpritId: SuspectId;
  readonly fact: boolean;
  /** Display name from the matching Suspect, for rendering without a separate lookup. */
  readonly suspectDisplayName: string;
};

/**
 * Build the Cartesian product of suspects × {false, true} as an ordered array of six Hypothesis
 * objects. The suspects are emitted in the order given by `displayOrder`; within each suspect,
 * fact=false appears before fact=true.
 *
 * - Does NOT mutate `suspects` or `displayOrder`.
 * - Does NOT call the solver, read private answer data, or access any UI or storage layer.
 * - Returns a new array on every call; callers may mutate the result without affecting inputs.
 *
 * @param suspects     All Suspect objects for the current case (used for displayName lookup).
 * @param displayOrder The SuspectId ordering that controls card layout (matches publicSnapshot order).
 */
export function buildHypotheses(
  suspects: readonly Suspect[],
  displayOrder: readonly SuspectId[],
): Hypothesis[] {
  // Build a lookup map without mutating the input array.
  const nameById = new Map<SuspectId, string>();
  for (const suspect of suspects) {
    nameById.set(suspect.id, suspect.displayName);
  }

  const result: Hypothesis[] = [];
  for (const culpritId of displayOrder) {
    const suspectDisplayName = nameById.get(culpritId) ?? culpritId;
    result.push(
      {
        id: `${culpritId}-false` as HypothesisId,
        culpritId,
        fact: false,
        suspectDisplayName,
      },
      {
        id: `${culpritId}-true` as HypothesisId,
        culpritId,
        fact: true,
        suspectDisplayName,
      },
    );
  }
  return result;
}

// ── Re-export Locale so HypothesisBoard can import both from this one path if desired. ──
// (Locale is already in types.ts and exported from index.ts; this re-export is a convenience
//  only for files that import from hypothesis.ts directly, and does not duplicate the definition.)
export type { Locale };

'use client';

/**
 * HypothesisBoard.tsx — Player-owned manual deduction scratchpad.
 *
 * This component is Kiro work (2026-10-31). It is a pure client component with
 * local state only. It never reads the solver, case draft, role assignment, or
 * culprit identity. All eliminations are manual player decisions.
 *
 * The inherited application code (Game.tsx, CrossExamination.tsx, CSS, engine)
 * is Codex work. Codex is responsible for rendering this component and styling
 * the hypothesis-board / hypothesis-grid / hypothesis-card class names.
 */

import { useState } from 'react';
import { buildHypotheses, type Hypothesis, type HypothesisId } from '@/lib/game/hypothesis';
import type { Locale, Suspect, SuspectId } from '@/lib/game/types';

type Props = {
  suspects: readonly Suspect[];
  locale: Locale;
  /** factLabels[0] = label for fact=false event; factLabels[1] = label for fact=true event. */
  factLabels: readonly [string, string];
};

/** Inline localizer — same pattern as CrossExamination.tsx. */
function useT(locale: Locale) {
  return (ko: string, en: string) => locale === 'ko' ? ko : en;
}

/**
 * Manual six-world hypothesis board.
 *
 * Renders six toggleable cards representing every (culpritId × fact) world.
 * The player eliminates worlds they consider impossible; the board never
 * auto-eliminates or reveals which world is correct.
 */
export default function HypothesisBoard({ suspects, locale, factLabels }: Props) {
  const t = useT(locale);

  // Derive display order from the suspects array (mirrors publicSnapshot ordering).
  const displayOrder: SuspectId[] = suspects.map((s) => s.id as SuspectId);
  const hypotheses: Hypothesis[] = buildHypotheses(suspects, displayOrder);

  // Set of eliminated hypothesis IDs; never mutated — always replaced with a new Set.
  const [eliminated, setEliminated] = useState<Set<HypothesisId>>(new Set());

  function toggle(id: HypothesisId) {
    setEliminated((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }

  function reset() {
    setEliminated(new Set());
  }

  const total = hypotheses.length;             // always 6
  const remaining = total - eliminated.size;

  // The one remaining card — only meaningful when exactly one is left.
  const lastCard: Hypothesis | undefined =
    remaining === 1 ? hypotheses.find((h) => !eliminated.has(h.id)) : undefined;

  return (
    <section
      className="hypothesis-board"
      data-testid="hypothesis-board"
      aria-label={t('가설 보드', 'Hypothesis board')}
    >
      <h2>{t('내 가설 보드', 'My hypothesis board')}</h2>

      <p className="hypothesis-instruction">
        {t(
          '각 카드를 눌러 제외할 수 있어요. 자동으로 제외되거나 정답을 알려주지 않아요.',
          'Tap a card to eliminate it. Nothing is eliminated automatically, and no answer is revealed.',
        )}
      </p>

      {/* Remaining count */}
      <p className="hypothesis-count" aria-live="polite">
        {t(`남은 가설: ${remaining} / ${total}`, `Remaining: ${remaining} / ${total}`)}
        {remaining === 1 && lastCard && (
          <>
            {' — '}
            <strong>{t('내가 남긴 가설', 'My remaining theory')}</strong>
          </>
        )}
      </p>

      {/* Zero-remaining message */}
      {remaining === 0 && (
        <p className="hypothesis-empty" role="status">
          {t(
            '모든 가설을 제외했어요. 초기화 버튼으로 다시 시작할 수 있어요.',
            'All hypotheses eliminated. Use the reset button to restore the cards.',
          )}
        </p>
      )}

      <div className="hypothesis-grid">
        {hypotheses.map((h) => {
          const isEliminated = eliminated.has(h.id);
          const factLabel = h.fact ? factLabels[1] : factLabels[0];
          const statusText = isEliminated
            ? t('제외됨', 'Eliminated')
            : t('가능', 'Possible');
          const isLast = lastCard?.id === h.id;

          return (
            <button
              key={h.id}
              className="hypothesis-card"
              data-testid={`hypothesis-card-${h.id}`}
              aria-pressed={isEliminated}
              onClick={() => toggle(h.id)}
              type="button"
            >
              <span className="hypothesis-suspect">{h.suspectDisplayName}</span>
              <span className="hypothesis-fact">{factLabel}</span>
              <span className="hypothesis-status">{statusText}</span>
              {isLast && (
                <span className="hypothesis-last-label">
                  {t('내가 남긴 가설', 'My remaining theory')}
                </span>
              )}
            </button>
          );
        })}
      </div>

      <button
        className="hypothesis-reset"
        data-testid="hypothesis-reset"
        onClick={reset}
        type="button"
      >
        {t('가설 초기화', 'Reset hypotheses')}
      </button>
    </section>
  );
}

